<script setup lang="ts">
import type {Video} from '../../shared/types'
const session=useSession(),videos=ref<Video[]>([]),busy=ref(true),error=ref(''),query=ref('')
const filtered=computed(()=>videos.value.filter(v=>`${v.title} ${v.category} ${v.description}`.toLowerCase().includes(query.value.toLowerCase())))
onMounted(async()=>{await session.refresh();if(session.user.value)try{videos.value=(await $fetch<{videos:Video[]}>('/api/videos')).videos}catch(e){error.value=apiMessage(e)}busy.value=false})
</script>
<template><div class="container page"><div class="page-heading"><div class="eyebrow">Biblioteca de conhecimento</div><h1>Central de Aprendizado</h1><p>Treinamentos, orientações e tutoriais práticos para ampliar o conhecimento da operação.</p></div><div v-if="busy" class="empty">Carregando vídeos...</div><div v-else-if="!session.user.value" class="panel panel-pad"><h2>Acesso para colaboradores</h2><p class="muted">Faça login para visualizar os treinamentos internos.</p><NuxtLink to="/login" class="btn btn-primary">Entrar</NuxtLink></div><div v-else><div v-if="error" class="error">{{error}}</div><div class="search-row"><input v-model="query" class="search-input" type="search" placeholder="Pesquisar vídeos e categorias..."></div><div v-if="filtered.length" class="video-grid"><article v-for="video in filtered" :key="video.id" class="video-card"><div class="video-wrap"><iframe :src="video.embed_url" :title="video.title" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="fullscreen; picture-in-picture" allowfullscreen/></div><h3>{{video.title}}</h3><p>{{video.description}}</p><a class="inline-link" :href="video.external_url" rel="noopener noreferrer" target="_blank">Abrir em nova guia ↗</a></article></div><div v-else class="empty">Ainda não há vídeos publicados. A liderança pode cadastrá-los no painel.</div></div></div></template>
